function sellerRemediation(shop=0){refreshAdminCatalog();const ss=shopSupervision[shop],items=[...adminCatalog.values()].filter(p=>p.shop===shop&&productControl(p.id).records.length);modal('商家通知与整改 · 预览',`<label>预览店铺 <select id="remediationShop">${shops.map((n,i)=>`<option value="${i}" ${shop===i?'selected':''}>${escapeHTML(n)}</option>`).join('')}</select></label><section class="reportTarget"><h3>${ss.stopped?'暂停营业':'正常营业'}</h3>${ss.records.map(r=>`<p>${adminActionLabel(r.action)}：${escapeHTML(r.reason)}</p>`).join('')||'<p>暂无店铺通知</p>'}${ss.request?`<p>恢复申请：${ss.request.status} · ${escapeHTML(ss.request.result||ss.request.reason)}</p>`:''}${ss.stopped?`<button data-remedy-scope="shop" data-remedy-id="${shop}" ${ss.request?.status==='待审核'?'disabled':''}>申请恢复营业</button>`:''}</section><h3>商品通知</h3>${items.map(p=>{const s=productControl(p.id);return `<section class="reportTarget"><b>${escapeHTML(p.name)}</b><p>${s.blocked?'紧急下架限制中':!s.listed?'限制已解除，等待商家上架':'正常经营'}</p>${s.records.map(r=>`<p>${adminActionLabel(r.action)}：${escapeHTML(r.reason)}</p>`).join('')}${s.request?`<p>复核：${s.request.status} · ${escapeHTML(s.request.result||s.request.reason)}</p>`:''}${s.blocked?`<button data-remedy-scope="product" data-remedy-id="${p.id}" ${s.request?.status==='待审核'?'disabled':''}>修改资料并申请复核</button>`:!s.listed?`<button data-remedy-publish="${p.id}">重新上架</button>`:''}</section>`;}).join('')||'<p>暂无商品通知</p>'}<div class="orderActions"><button id="remedyClose">返回</button><button id="remedyAdmin">前往管理员审核预览</button></div>`);$('remediationShop').onchange=e=>sellerRemediation(+e.target.value);$('remedyClose').onclick=()=>$('dialog').close();$('remedyAdmin').onclick=()=>openAdmin('shops','requests');document.querySelectorAll('[data-remedy-scope]').forEach(b=>b.onclick=()=>remedyForm(b.dataset.remedyScope,+b.dataset.remedyId,shop));document.querySelectorAll('[data-remedy-publish]').forEach(b=>b.onclick=()=>{const p=adminCatalog.get(+b.dataset.remedyPublish),s=productControl(p.id),own=createdProducts.find(x=>x.productId===p.id);if(!AdminModel.canPublish({...s,stopped:shopSupervision[shop].stopped},own?.category==='licensed'?qualifiedNow():true,!!own?.deleted)){toast('店铺状态、资质或商品限制不满足上架条件');return;}if(own){const errors=ProductEditorModel.errors(own,true,qualifiedNow());if(errors.length){toast(errors.join('；'));return;}own.status='在售';}s.listed=true;adminLog('product',p.id,'商家重新上架','复核通过后自行上架');applyAdminVisibility();sellerRemediation(shop);});}
function remedyForm(scope,id,shop){const p=scope==='product'?adminCatalog.get(id):null;modal(scope==='shop'?'申请恢复营业':'商品整改复核',`${p?`<label class="reportField">修改商品说明<textarea id="remedyDescription">${escapeHTML(p.description||'')}</textarea></label>`:''}<label class="reportField">整改说明<textarea id="remedyReason" required placeholder="说明已经完成哪些整改"></textarea></label><p id="remedyError" role="alert"></p><div class="orderActions"><button id="remedyBack">返回</button><button id="remedySubmit" class="primary">提交申请</button></div>`);$('remedyBack').onclick=()=>sellerRemediation(shop);$('remedySubmit').onclick=()=>{try{const reason=$('remedyReason').value;const state=scope==='shop'?shopSupervision[id]:productControl(id),next=AdminModel.act(state,'request',reason);if(scope==='shop')shopSupervision[id]=next;else{const description=$('remedyDescription').value.trim();if(!description)throw Error('请填写修改后的商品说明');productSupervision[id]=next;p.description=description;const own=createdProducts.find(x=>x.productId===id);if(own)own.description=description;}adminLog(scope,id,'提交整改申请',reason);sellerRemediation(shop);}catch(e){$('remedyError').textContent=e.message;}};}
const adminSellerShowBase=showSeller;showSeller=function(section){adminSellerShowBase(section);adminPage.hidden=true;const badge=sellerReviewPage.querySelector('.sellerIdentity .tag');if(badge)badge.textContent=shopSupervision[0].stopped?'暂停营业':'正常营业';$('sellerContent').insertAdjacentHTML('afterbegin',`<div class="adminSellerNotice"><span>${shopSupervision[0].stopped?'店铺暂停营业，请整改后申请恢复。':'查看平台警告、商品限制及整改进度'}</span><button id="sellerAdminNotices">通知与整改</button><button id="sellerAdminPreview">管理员预览</button></div>`);$('sellerAdminNotices').onclick=()=>sellerRemediation(0);$('sellerAdminPreview').onclick=()=>openAdmin();};
const adminQualificationsBase=showQualificationForm;showQualificationForm=function(back){adminQualificationsBase(back);if($('qualificationReview'))$('qualificationReview').onclick=()=>reviewQualification();};
const adminApplicationBase=showApplicationPage;showApplicationPage=function(kind){adminApplicationBase(kind);if($('reviewTextApplication'))$('reviewTextApplication').onclick=reviewApplication;};
const adminMineBase=showMine;showMine=function(){adminMineBase();const reset=$('resetDemo').onclick;$('resetDemo').onclick=()=>{for(const [id,p] of adminCatalog)if(!p.editorId&&!products.some(x=>x.id===id))products.push(p);shopSupervision=shops.map(()=>AdminModel.initial());productSupervision={};adminRecords=[];reset();adminCatalog=new Map(products.map(p=>[p.id,p]));};};$('mine').onclick=showMine;
if(location.hash.startsWith('#seller-'))showSeller(location.hash.slice(8));
